"""Small shared helpers for reading the plain-text files."""

import datetime
import re

# Digits only ever mean ASCII 0-9 (``int()`` alone would take ``_`` and
# Unicode digits).  Absurdly long numbers are refused instead of being
# handed to ``int()``, which has a conversion length limit.
MAX_DIGITS = 1000

_DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_UINT = re.compile(r"[0-9]+")
_SINT = re.compile(r"[+-]?[0-9]+")
_PRICE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
ORDER_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_SEP = re.compile(r"[ \t]+")


def iter_lines(text):
    """Yield ``(line_number, line)`` for every line that carries data.

    Lines end at LF (one CR before it is dropped); a BOM at the very start is
    ignored; blank and ``#`` comment lines are skipped but still counted.
    """
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        yield number, line


def split_fields(line, count=None):
    """Split on runs of spaces and tabs only; ``count`` fields at most."""
    line = line.strip(" \t")
    if count is None:
        return _SEP.split(line)
    return _SEP.split(line, count - 1)


def parse_date(text):
    """A real ``YYYY-MM-DD`` date, or ``None``."""
    if not _DATE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        return None


def _digits_ok(digits):
    return len(digits.lstrip("0")) <= MAX_DIGITS


def parse_uint(text):
    """A whole number written with ASCII digits only, or ``None``."""
    if not _UINT.fullmatch(text) or not _digits_ok(text):
        return None
    return int(text.lstrip("0") or "0")


def parse_sint(text):
    """A whole number with an optional sign, or ``None``."""
    if not _SINT.fullmatch(text) or not _digits_ok(text):
        return None
    sign = -1 if text[0] == "-" else 1
    digits = text.lstrip("+-")
    return sign * int(digits.lstrip("0") or "0")


def is_price(text):
    """True when ``text`` is a plain non-negative amount, two decimals at most."""
    return bool(_PRICE.fullmatch(text)) and _digits_ok(text.split(".")[0])
