"""Parsers for catalog.txt, movements.txt and orders.txt."""

import dataclasses
import datetime
from decimal import Decimal

from ._text import (ORDER_RE, SKU_RE, is_price, iter_lines, parse_date,
                    parse_sint, parse_uint, split_fields)
from .errors import ParseError
from .shelves import check_stock

TAX_RATES = ("standard", "reduced", "zero")


@dataclasses.dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclasses.dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = dataclasses.field(default=0, compare=False)


@dataclasses.dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: list
    line: int = dataclasses.field(default=0, compare=False)


def parse_catalog(text):
    """Parse catalog.txt into ``{SKU: Product}``."""
    catalog = {}
    for number, line in iter_lines(text):
        parts = line.split("|")
        if len(parts) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|'")
        sku, name, price, reorder = (p.strip() for p in parts[:4])
        if not SKU_RE.fullmatch(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "empty name")
        if not is_price(price) or Decimal(price) < Decimal("0.01"):
            raise ParseError(number, "bad price %r" % price)
        qty = parse_uint(reorder)
        if qty is None:
            raise ParseError(number, "bad reorder level %r" % reorder)
        tax = "standard"
        if len(parts) == 5:
            raw = parts[4].strip()
            tax = raw.lower() if raw.isascii() else ""
            if tax not in TAX_RATES:
                raise ParseError(number, "bad tax %r" % raw)
        catalog[sku] = Product(sku, name, Decimal(price), qty, tax)
    return catalog


def parse_movements(text, catalog):
    """Parse movements.txt; stock may never go below zero in (date, file) order."""
    movements = []
    for number, line in iter_lines(text):
        parts = split_fields(line, 4)
        if len(parts) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date = parse_date(parts[0])
        if date is None:
            raise ParseError(number, "bad date %r" % parts[0])
        if not SKU_RE.fullmatch(parts[1]) or parts[1].upper() not in catalog:
            raise ParseError(number, "unknown SKU %r" % parts[1])
        quantity = parse_sint(parts[2])
        if quantity is None or quantity == 0:
            raise ParseError(number, "bad quantity %r" % parts[2])
        note = parts[3].strip() if len(parts) == 4 else ""
        movements.append(Movement(date, parts[1].upper(), quantity, note, number))
    check_stock(movements)
    return movements


def parse_orders(text, catalog):
    """Parse orders.txt into a list of :class:`Order`."""
    orders = []
    seen = set()
    for number, line in iter_lines(text):
        parts = split_fields(line)
        if len(parts) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        if not ORDER_RE.fullmatch(parts[0]):
            raise ParseError(number, "bad order number %r" % parts[0])
        order_id = parts[0].upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(parts[1])
        if date is None:
            raise ParseError(number, "bad date %r" % parts[1])
        lines = []
        skus = set()
        for pair in parts[3].split(","):
            sku, star, qty = pair.partition("*")
            if not star or not SKU_RE.fullmatch(sku):
                raise ParseError(number, "bad order line %r" % pair)
            sku = sku.upper()
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %s" % sku)
            if sku in skus:
                raise ParseError(number, "SKU %s appears twice" % sku)
            quantity = parse_uint(qty)
            if quantity is None or quantity < 1:
                raise ParseError(number, "bad quantity %r" % qty)
            skus.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, date, parts[2], lines, number))
    return orders
