"""Stock levels, low stock and history."""

from .errors import ParseError


def _counting_order(movements):
    return sorted(range(len(movements)), key=lambda i: (movements[i].date, i))


def check_stock(movements):
    """Raise ParseError at the movement that first takes a SKU below zero."""
    balance = {}
    for i in _counting_order(movements):
        move = movements[i]
        total = balance.get(move.sku, 0) + move.quantity
        balance[move.sku] = total
        if total < 0:
            raise ParseError(move.line, "stock of %s would go below zero" % move.sku)


def stock_levels(catalog, movements):
    """``{SKU: on hand}`` for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        levels[move.sku] = levels.get(move.sku, 0) + move.quantity
    return levels


def status(onhand, reorder):
    if onhand == 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def low_stock(catalog, movements):
    """``[(product, onhand, buy)]`` for every low or out product, by SKU."""
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        product = catalog[sku]
        if status(levels[sku], product.reorder) != "ok":
            buy = max(1, 2 * product.reorder - levels[sku])
            rows.append((product, levels[sku], buy))
    return rows


def history(sku, movements):
    """``[(movement, balance)]`` for one SKU in the order the movements count."""
    rows = []
    balance = 0
    for i in _counting_order(movements):
        if movements[i].sku == sku:
            balance += movements[i].quantity
            rows.append((movements[i], balance))
    return rows


def capacity(movements, sku, date):
    """Most that can be shipped out of ``sku`` on ``date`` without ever
    taking a later balance below zero."""
    at_date = 0
    later_min = None
    balance = 0
    for i in _counting_order(movements):
        move = movements[i]
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= date:
            at_date = balance
        elif later_min is None or balance < later_min:
            later_min = balance
    best = at_date if later_min is None else min(at_date, later_min)
    return max(best, 0)
